                <tr key={t.id} className="hover:bg-zinc-50 dark:hover:bg-zinc-900/50">
                  <td className="px-6 py-4 font-medium text-zinc-900 dark:text-zinc-100">{t.name}</td>
                  <td className="px-6 py-4 text-zinc-500">{t.slug}</td>
