      slug: p.slug,
      shortDescription: p.description || '',
      fullDescription: (meta.fullDescription as string) || p.description || '',
      coverImageUrl: (meta.coverImageUrl as string) || '/hero/hero-01.png',
      accentColor: (meta.accentColor as string) || '#172B6B',
