}

'use client';

import { useRouter } from 'next/navigation';
import { useState, useTransition } from 'react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { createEvent, updateEvent, uploadEventImage } from '@/features/events/actions';
import type { EventRow } from '@/features/events/repository';
import type { CreateEventDTO } from '@/features/events/validators';

interface EventFormProps {
  initialData?: EventRow;
  programs: { id: string; title: string }[];
}

export function EventForm({ initialData, programs }: EventFormProps) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);

  const initialMetadata = initialData?.metadata as Record<string, any> || {};

  const [formData, setFormData] = useState<Partial<CreateEventDTO>>({
    event_code: initialData?.event_code || '',
    slug: initialData?.slug || '',
    title: initialData?.title || '',
    subtitle: initialData?.subtitle || '',
    description: initialData?.description || '',
    program_id: initialData?.program_id || (programs.length > 0 ? programs[0].id : ''),
    status: (initialData?.status as 'Draft' | 'Published' | 'Registration Open' | 'Registration Closed' | 'Completed' | 'Cancelled' | 'Archived') || 'Draft',
    visibility: (initialData?.visibility as 'public' | 'private' | 'internal') || 'public',
    event_type: initialData?.event_type || '',
    start_time: initialData?.start_time ? new Date(initialData.start_time).toISOString().slice(0, 16) : '',
    end_time: initialData?.end_time ? new Date(initialData.end_time).toISOString().slice(0, 16) : '',
    venue_name: initialData?.venue_name || '',
    address_line1: initialData?.address_line1 || '',
    address_line2: initialData?.address_line2 || '',
    city: initialData?.city || '',
    state: initialData?.state || '',
    postal_code: initialData?.postal_code || '',
    country: initialData?.country || '',
    max_attendees: initialData?.max_attendees || 0,
    cover_image_id: initialData?.cover_image_id || '',
    is_featured: initialData?.is_featured || false,
    is_virtual: initialMetadata.is_virtual || false,
    virtual_link: initialMetadata.virtual_link || '',
    registration_deadline: initialMetadata.registration_deadline ? new Date(initialMetadata.registration_deadline).toISOString().slice(0, 16) : '',
  });

  const [uploadingImage, setUploadingImage] = useState(false);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      setUploadingImage(true);
      setError(null);

      const formDataUpload = new FormData();
      formDataUpload.append('file', file);

      const res = await uploadEventImage(formDataUpload);
      if (!res.success || !res.data) throw new Error(res.error || 'Upload failed');
      setFormData(prev => ({ ...prev, cover_image_id: res.data }));
    } catch (err: any) {
      setError(err.message || 'Image upload failed.');
    } finally {
      setUploadingImage(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    setFormData((prev) => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : type === 'number' ? Number(value) : value,
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    startTransition(async () => {
      try {
        const payload: CreateEventDTO = {
          event_code: formData.event_code || '',
          slug: formData.slug || (formData.title || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)+/g, ''),
          title: formData.title || '',
          subtitle: formData.subtitle || undefined,
          description: formData.description || undefined,
          program_id: formData.program_id || programs[0]?.id || '',
          status: formData.status as 'Draft' | 'Published' | 'Registration Open' | 'Registration Closed' | 'Completed' | 'Cancelled' | 'Archived',
          visibility: formData.visibility as 'public' | 'private' | 'internal',
          event_type: formData.event_type || 'General',
          start_time: formData.start_time ? new Date(formData.start_time).toISOString() : undefined,
          end_time: formData.end_time ? new Date(formData.end_time).toISOString() : undefined,
          venue_name: formData.venue_name || undefined,
          address_line1: formData.address_line1 || undefined,
          address_line2: formData.address_line2 || undefined,
          city: formData.city || undefined,
          state: formData.state || undefined,
          postal_code: formData.postal_code || undefined,
          country: formData.country || undefined,
          latitude: formData.latitude || undefined,
          longitude: formData.longitude || undefined,
          is_virtual: formData.is_virtual || false,
          virtual_link: formData.virtual_link || undefined,
          max_attendees: formData.max_attendees || undefined,
          registration_deadline: formData.registration_deadline ? new Date(formData.registration_deadline).toISOString() : undefined,
          cover_image_id: formData.cover_image_id || undefined,
          is_featured: formData.is_featured || false,
          metadata: initialData?.metadata || {},
        };

        if (initialData) {
          await updateEvent(initialData.id, payload);
        } else {
          await createEvent(payload);
        }

        router.push('/admin/dashboard/events');
        router.refresh();
      } catch (err: any) {
        setError(err.message || 'An error occurred while saving the event.');
      }
    });
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6 max-w-4xl bg-white p-8 rounded-lg shadow-sm border border-gray-100">
      {error && (
        <div className="p-4 bg-red-50 text-red-700 text-sm rounded-md border border-red-100">
          {error}
        </div>
      )}

      {/* CORE INFORMATION */}
      <h3 className="text-lg font-semibold border-b pb-2">Core Details</h3>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-2">
          <Label htmlFor="event_code">Event Code *</Label>
          <Input id="event_code" name="event_code" value={formData.event_code} onChange={handleChange} placeholder="e.g. EVT-2026-01" required disabled={!!initialData} />
        </div>
        <div className="space-y-2">
          <Label htmlFor="program_id">Associated Program *</Label>
          <select id="program_id" name="program_id" value={formData.program_id} onChange={handleChange} className="w-full flex h-10 rounded-md border border-input bg-background px-3 py-2 text-sm" required>
            <option value="" disabled>Select a Program</option>
            {programs.map(p => (
              <option key={p.id} value={p.id}>{p.title}</option>
            ))}
          </select>
        </div>
        <div className="space-y-2 md:col-span-2">
          <Label htmlFor="title">Event Title *</Label>
          <Input id="title" name="title" value={formData.title} onChange={handleChange} placeholder="Event Title" required />
        </div>
        <div className="space-y-2 md:col-span-2">
          <Label htmlFor="subtitle">Subtitle / Short Description</Label>
          <Input id="subtitle" name="subtitle" value={formData.subtitle || ''} onChange={handleChange} placeholder="Brief summary" />
        </div>
        <div className="space-y-2 md:col-span-2">
          <Label htmlFor="description">Full Description</Label>
          <textarea id="description" name="description" value={formData.description || ''} onChange={handleChange} rows={5} className="w-full flex rounded-md border border-input bg-background px-3 py-2 text-sm" placeholder="Detailed description..." />
        </div>
      </div>

      {/* CLASSIFICATION */}
      <h3 className="text-lg font-semibold border-b pb-2 pt-4">Classification</h3>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-2">
          <Label htmlFor="status">Status</Label>
          <select id="status" name="status" value={formData.status} onChange={handleChange} className="w-full flex h-10 rounded-md border border-input bg-background px-3 py-2 text-sm">
            <option value="Draft">Draft</option>
            <option value="Published">Published</option>
            <option value="Registration Open">Registration Open</option>
            <option value="Registration Closed">Registration Closed</option>
            <option value="Completed">Completed</option>
            <option value="Cancelled">Cancelled</option>
            <option value="Archived">Archived</option>
          </select>
        </div>
        <div className="space-y-2">
          <Label htmlFor="event_type">Event Type *</Label>
          <Input id="event_type" name="event_type" value={formData.event_type} onChange={handleChange} placeholder="e.g. Workshop, Seminar" required />
        </div>
        <div className="space-y-2">
          <Label htmlFor="visibility">Visibility</Label>
          <select id="visibility" name="visibility" value={formData.visibility} onChange={handleChange} className="w-full flex h-10 rounded-md border border-input bg-background px-3 py-2 text-sm">
            <option value="public">Public</option>
            <option value="private">Private</option>
            <option value="internal">Internal</option>
          </select>
        </div>
      </div>

      {/* TIMING & REGISTRATION */}
      <h3 className="text-lg font-semibold border-b pb-2 pt-4">Timing & Registration</h3>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-2">
          <Label htmlFor="start_time">Start Time</Label>
          <Input type="datetime-local" id="start_time" name="start_time" value={formData.start_time || ''} onChange={handleChange} />
        </div>
        <div className="space-y-2">
          <Label htmlFor="end_time">End Time</Label>
          <Input type="datetime-local" id="end_time" name="end_time" value={formData.end_time || ''} onChange={handleChange} />
        </div>
        <div className="space-y-2">
          <Label htmlFor="registration_deadline">Registration Deadline</Label>
          <Input type="datetime-local" id="registration_deadline" name="registration_deadline" value={(formData.registration_deadline as string) || ''} onChange={handleChange} />
        </div>
        <div className="space-y-2">
          <Label htmlFor="max_attendees">Capacity (Max Attendees)</Label>
          <Input type="number" min={0} id="max_attendees" name="max_attendees" value={formData.max_attendees || 0} onChange={handleChange} />
        </div>
      </div>

      {/* LOCATION & VENUE */}
      <h3 className="text-lg font-semibold border-b pb-2 pt-4">Location & Virtual</h3>
      <div className="flex items-center gap-2 mb-4">
        <input type="checkbox" id="is_virtual" name="is_virtual" checked={formData.is_virtual} onChange={handleChange} className="h-4 w-4 text-blue-600" />
        <Label htmlFor="is_virtual">This is a virtual/online event</Label>
      </div>

      {formData.is_virtual && (
        <div className="space-y-2 mb-4">
          <Label htmlFor="virtual_link">Virtual Meeting Link</Label>
          <Input type="url" id="virtual_link" name="virtual_link" value={formData.virtual_link as string} onChange={handleChange} placeholder="https://zoom.us/j/123456" />
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-2 md:col-span-2">
          <Label htmlFor="venue_name">Venue Name</Label>
          <Input id="venue_name" name="venue_name" value={formData.venue_name || ''} onChange={handleChange} placeholder="e.g. Main Auditorium" />
        </div>
        <div className="space-y-2 md:col-span-2">
          <Label htmlFor="address_line1">Address Line 1</Label>
          <Input id="address_line1" name="address_line1" value={formData.address_line1 || ''} onChange={handleChange} />
        </div>
        <div className="space-y-2">
          <Label htmlFor="city">City</Label>
          <Input id="city" name="city" value={formData.city || ''} onChange={handleChange} />
        </div>
        <div className="space-y-2">
          <Label htmlFor="state">State</Label>
          <Input id="state" name="state" value={formData.state || ''} onChange={handleChange} />
        </div>
        <div className="space-y-2">
          <Label htmlFor="postal_code">Postal Code</Label>
          <Input id="postal_code" name="postal_code" value={formData.postal_code || ''} onChange={handleChange} />
        </div>
      </div>

      {/* MEDIA */}
      <h3 className="text-lg font-semibold border-b pb-2 pt-4">Media</h3>
      <div className="space-y-2">
        <Label htmlFor="cover_image">Cover Image Upload</Label>
        <Input id="cover_image" type="file" accept="image/*" onChange={handleImageUpload} disabled={uploadingImage || isPending} />
        {uploadingImage && <p className="text-sm text-blue-600">Uploading image...</p>}
        {formData.cover_image_id && <p className="text-sm text-green-600">Image attached successfully.</p>}
      </div>

      <div className="flex items-center gap-2 pt-4 border-t border-gray-100">
        <input type="checkbox" id="is_featured" name="is_featured" checked={formData.is_featured} onChange={handleChange} className="h-4 w-4" />
        <Label htmlFor="is_featured">Feature on Homepage / Directory</Label>
      </div>

      <div className="pt-4 border-t border-gray-100 flex justify-end gap-4">
        <Button type="button" variant="outline" onClick={() => router.push('/admin/dashboard/events')} disabled={isPending}>
          Cancel
        </Button>
        <Button type="submit" disabled={isPending}>
          {isPending ? 'Saving...' : initialData ? 'Update Event' : 'Create Event'}
        </Button>
      </div>
    </form>
  );
}

'use client';

import { useRouter } from 'next/navigation';
import { useState, useTransition } from 'react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { createAlbum, updateAlbum } from '@/features/gallery/actions';
import type { AlbumRow } from '@/features/gallery/repository';
import type { CreateAlbumDTO } from '@/features/gallery/validators';
import { uploadMedia } from '@/features/media/actions';

interface GalleryAlbumFormProps {
  initialData?: AlbumRow;
  programs: { id: string; title: string }[];
  events: { id: string; title: string }[];
}

export function GalleryAlbumForm({ initialData, programs, events }: GalleryAlbumFormProps) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const [uploadingImage, setUploadingImage] = useState(false);

  const [formData, setFormData] = useState<Partial<CreateAlbumDTO>>({
    album_code: initialData?.album_code || '',
    slug: initialData?.slug || '',
    title: initialData?.title || '',
    description: initialData?.description || '',
    visibility: (initialData?.visibility as 'public' | 'members' | 'private' | 'hidden') || 'public',
    cover_image_id: initialData?.cover_image_id || null,
    program_id: initialData?.program_id || null,
    event_id: initialData?.event_id || null,
    is_featured: initialData?.is_featured || false,
    display_order: initialData?.display_order || 0,
  });

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      setUploadingImage(true);
      setError(null);
      const data = new FormData();
      data.append('file', file);
      data.append('folder', 'gallery-covers');

      const result = await uploadMedia(data);
      if (!result.success || !result.data) {
        throw new Error(result.error || 'Failed to upload cover image');
      }

      setFormData((prev) => ({ ...prev, cover_image_id: result.data!.id }));
    } catch (err: any) {
      setError(err.message || 'Error uploading cover image');
    } finally {
      setUploadingImage(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    startTransition(async () => {
      try {
        const payload: CreateAlbumDTO = {
          album_code: formData.album_code || `GAL-${Date.now().toString().slice(-6)}`,
          slug: formData.slug || formData.title?.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') || '',
          title: formData.title || '',
          description: formData.description || null,
          visibility: (formData.visibility as 'public' | 'members' | 'private' | 'hidden') || 'public',
          cover_image_id: formData.cover_image_id || null,
          program_id: formData.program_id ? formData.program_id : null,
          event_id: formData.event_id ? formData.event_id : null,
          is_featured: Boolean(formData.is_featured),
          display_order: Number(formData.display_order) || 0,
        };

        let result;
        if (initialData) {
          result = await updateAlbum(initialData.id, payload);
        } else {
          result = await createAlbum(payload);
        }

        if (!result.success) {
          setError(result.error || 'Failed to save album');
          return;
        }

        router.push('/admin/dashboard/gallery');
        router.refresh();
      } catch (err: any) {
        setError(err.message || 'An error occurred while saving the album');
      }
    });
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6 max-w-3xl bg-white p-6 rounded-lg shadow">
      {error && (
        <div className="p-4 bg-red-50 text-red-700 rounded-md border border-red-200">
          {error}
        </div>
      )}

      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label htmlFor="album_code">Album Code</Label>
          <Input
            id="album_code"
            value={formData.album_code || ''}
            onChange={(e) => setFormData({ ...formData, album_code: e.target.value.toUpperCase() })}
            placeholder="GAL-001"
            disabled={!!initialData || isPending}
            required
          />
        </div>

        <div>
          <Label htmlFor="slug">Slug</Label>
          <Input
            id="slug"
            value={formData.slug || ''}
            onChange={(e) => setFormData({ ...formData, slug: e.target.value })}
            placeholder="annual-gala-2026"
            disabled={isPending}
            required
          />
        </div>
      </div>

      <div>
        <Label htmlFor="title">Title</Label>
        <Input
          id="title"
          value={formData.title || ''}
          onChange={(e) => setFormData({ ...formData, title: e.target.value })}
          placeholder="Annual Charity Gala 2026"
          disabled={isPending}
          required
        />
      </div>

      <div>
        <Label htmlFor="description">Description</Label>
        <textarea
          id="description"
          value={formData.description || ''}
          onChange={(e) => setFormData({ ...formData, description: e.target.value })}
          rows={3}
          className="w-full px-3 py-2 border rounded-md"
          placeholder="Detailed summary of the album..."
          disabled={isPending}
        />
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label htmlFor="program_id">Associated Program (Optional)</Label>
          <select
            id="program_id"
            value={formData.program_id || ''}
            onChange={(e) => setFormData({ ...formData, program_id: e.target.value || null })}
            className="w-full px-3 py-2 border rounded-md"
            disabled={isPending}
          >
            <option value="">None</option>
            {programs.map((program) => (
              <option key={program.id} value={program.id}>
                {program.title}
              </option>
            ))}
          </select>
        </div>

        <div>
          <Label htmlFor="event_id">Associated Event (Optional)</Label>
          <select
            id="event_id"
            value={formData.event_id || ''}
            onChange={(e) => setFormData({ ...formData, event_id: e.target.value || null })}
            className="w-full px-3 py-2 border rounded-md"
            disabled={isPending}
          >
            <option value="">None</option>
            {events.map((event) => (
              <option key={event.id} value={event.id}>
                {event.title}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <Label htmlFor="visibility">Visibility</Label>
          <select
            id="visibility"
            value={formData.visibility || 'public'}
            onChange={(e) => setFormData({ ...formData, visibility: e.target.value as any })}
            className="w-full px-3 py-2 border rounded-md"
            disabled={isPending}
          >
            <option value="public">Public</option>
            <option value="members">Members</option>
            <option value="private">Private</option>
            <option value="hidden">Hidden</option>
          </select>
        </div>

        <div>
          <Label htmlFor="display_order">Display Order</Label>
          <Input
            id="display_order"
            type="number"
            min={0}
            value={formData.display_order || 0}
            onChange={(e) => setFormData({ ...formData, display_order: parseInt(e.target.value, 10) || 0 })}
            disabled={isPending}
          />
        </div>
      </div>

      <div className="flex items-center gap-2">
        <input
          type="checkbox"
          id="is_featured"
          checked={formData.is_featured || false}
          onChange={(e) => setFormData({ ...formData, is_featured: e.target.checked })}
          disabled={isPending}
          className="rounded border-gray-300"
        />
        <Label htmlFor="is_featured">Feature this album on public gallery homepage</Label>
      </div>

      <div className="space-y-2">
        <Label htmlFor="cover_image">Cover Image</Label>
        <Input
          id="cover_image"
          type="file"
          accept="image/*"
          onChange={handleImageUpload}
          disabled={isPending || uploadingImage}
        />
        {uploadingImage && <p className="text-sm text-gray-500">Uploading image to R2 storage...</p>}
        {formData.cover_image_id && (
          <p className="text-sm text-green-600">Cover image uploaded (ID: {formData.cover_image_id})</p>
        )}
      </div>

      <div className="flex justify-end gap-3 pt-4 border-t">
        <Button
          type="button"
          variant="outline"
          onClick={() => router.push('/admin/dashboard/gallery')}
          disabled={isPending || uploadingImage}
        >
          Cancel
        </Button>
        <Button type="submit" disabled={isPending || uploadingImage}>
          {isPending ? 'Saving...' : initialData ? 'Update Album' : 'Create Album'}
        </Button>
      </div>
    </form>
  );
}

'use client';

import { Trash2, Upload, Star } from 'lucide-react';
import Image from 'next/image';
import { useRouter } from 'next/navigation';
import { useState } from 'react';

import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { addGalleryItem, removeGalleryItem } from '@/features/gallery/actions';
import type { GalleryItemWithMedia } from '@/features/gallery/repository';
import { uploadMedia } from '@/features/media/actions';

interface GalleryItemManagerProps {
  albumId: string;
  albumTitle: string;
  initialItems: GalleryItemWithMedia[];
}

export function GalleryItemManager({ albumId, albumTitle, initialItems }: GalleryItemManagerProps) {
  const router = useRouter();
  const [items, setItems] = useState<GalleryItemWithMedia[]>(initialItems);
  const [error, setError] = useState<string | null>(null);
  const [uploading, setUploading] = useState(false);

  const [caption, setCaption] = useState('');
  const [title, setTitle] = useState('');
  const [displayOrder, setDisplayOrder] = useState(0);
  const [isFeatured, setIsFeatured] = useState(false);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      setUploading(true);
      setError(null);

      const data = new FormData();
      data.append('file', file);
      data.append('folder', 'gallery-items');

      const uploadResult = await uploadMedia(data);
      if (!uploadResult.success || !uploadResult.data) {
        throw new Error(uploadResult.error || 'Failed to upload media to R2');
      }

      const mediaId = uploadResult.data.id;

      const addResult = await addGalleryItem({
        album_id: albumId,
        media_id: mediaId,
        title: title || file.name,
        caption: caption || null,
        display_order: displayOrder,
        is_featured: isFeatured,
      });

      if (!addResult.success || !addResult.data) {
        throw new Error(addResult.error || 'Failed to associate image with album');
      }

      setCaption('');
      setTitle('');
      setDisplayOrder(items.length + 1);
      setIsFeatured(false);

      router.refresh();
    } catch (err: any) {
      setError(err.message || 'Error adding gallery item');
    } finally {
      setUploading(false);
      e.target.value = '';
    }
  };

  const handleRemove = async (itemId: string) => {
    if (!confirm('Are you sure you want to remove this photo from the album?')) return;
    try {
      setError(null);
      const res = await removeGalleryItem(itemId, albumId);
      if (!res.success) {
        throw new Error(res.error || 'Failed to remove gallery item');
      }
      setItems((prev) => prev.filter((item) => item.id !== itemId));
      router.refresh();
    } catch (err: any) {
      setError(err.message || 'Error removing item');
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-lg shadow space-y-4">
        <h2 className="text-lg font-semibold text-gray-900">Add New Photo to &ldquo;{albumTitle}&rdquo;</h2>

        {error && (
          <div className="p-4 bg-red-50 text-red-700 rounded-md border border-red-200">
            {error}
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
            <Label htmlFor="item_title">Title / Credit (Optional)</Label>
            <Input
              id="item_title"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Photo by Jane Doe"
              disabled={uploading}
            />
          </div>

          <div>
            <Label htmlFor="item_caption">Caption (Optional)</Label>
            <Input
              id="item_caption"
              value={caption}
              onChange={(e) => setCaption(e.target.value)}
              placeholder="Students during workshop..."
              disabled={uploading}
            />
          </div>

          <div>
            <Label htmlFor="item_order">Display Order</Label>
            <Input
              id="item_order"
              type="number"
              min={0}
              value={displayOrder}
              onChange={(e) => setDisplayOrder(parseInt(e.target.value, 10) || 0)}
              disabled={uploading}
            />
          </div>
        </div>

        <div className="flex items-center gap-2">
          <input
            type="checkbox"
            id="item_featured"
            checked={isFeatured}
            onChange={(e) => setIsFeatured(e.target.checked)}
            disabled={uploading}
            className="rounded border-gray-300"
          />
          <Label htmlFor="item_featured">Highlight as Featured Image</Label>
        </div>

        <div>
          <Label htmlFor="file_upload" className="cursor-pointer inline-flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700">
            <Upload className="w-4 h-4" />
            {uploading ? 'Uploading...' : 'Select & Upload Photo'}
          </Label>
          <Input
            id="file_upload"
            type="file"
            accept="image/*"
            onChange={handleFileUpload}
            disabled={uploading}
            className="hidden"
          />
        </div>
      </div>

      <div className="bg-white p-6 rounded-lg shadow">
        <h3 className="text-lg font-semibold text-gray-900 mb-4">
          Album Photos ({initialItems.length})
        </h3>

        {initialItems.length === 0 ? (
          <p className="text-gray-500 py-6 text-center">No photos in this album yet.</p>
        ) : (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {initialItems.map((item) => (
              <div key={item.id} className="border rounded-lg overflow-hidden flex flex-col bg-gray-50">
                <div className="relative h-40 w-full bg-gray-200">
                  {item.media?.public_url ? (
                    <Image
                      src={item.media.public_url}
                      alt={item.media.alt_text || item.title || 'Album photo'}
                      fill
                      className="object-cover"
                    />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center text-gray-400 text-sm">
                      No Preview
                    </div>
                  )}
                  {item.is_featured && (
                    <span className="absolute top-2 left-2 bg-yellow-500 text-white p-1 rounded-full shadow">
                      <Star className="w-3.5 h-3.5 fill-current" />
                    </span>
                  )}
                </div>

                <div className="p-3 flex-1 flex flex-col justify-between">
                  <div>
                    {item.title && <p className="text-xs font-semibold text-gray-800 line-clamp-1">{item.title}</p>}
                    {item.caption && <p className="text-xs text-gray-600 mt-1 line-clamp-2">{item.caption}</p>}
                    <p className="text-xs text-gray-400 mt-1">Order: #{item.display_order}</p>
                  </div>

                  <div className="flex justify-end mt-3 pt-2 border-t border-gray-200">
                    <button
                      type="button"
                      onClick={() => handleRemove(item.id)}
                      className="text-red-600 hover:text-red-800 p-1"
                      title="Remove Photo"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useRouter } from 'next/navigation';
import { useState, useTransition } from 'react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { createProgram, updateProgram, uploadProgramImage } from '@/features/programs/actions';
import type { ProgramRow } from '@/features/programs/repository';
import type { CreateProgramDTO } from '@/features/programs/validators';

interface ProgramFormProps {
  initialData?: ProgramRow;
}

export function ProgramForm({ initialData }: ProgramFormProps) {
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [error, setError] = useState<string | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<CreateProgramDTO>>({
    program_code: initialData?.program_code || '',
    slug: initialData?.slug || '',
    title: initialData?.title || '',
    subtitle: initialData?.subtitle || '',
    description: initialData?.description || '',
    status: (initialData?.status as any) || 'draft',
    visibility: (initialData?.visibility as any) || 'public',
    is_featured: initialData?.is_featured || false,
    display_order: initialData?.display_order || 0,
    cover_image_id: initialData?.cover_image_id || '',
  });

  const [uploadingImage, setUploadingImage] = useState(false);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      setUploadingImage(true);
      setError(null);

      const formData = new FormData();
      formData.append('file', file);

      const res = await uploadProgramImage(formData);
      if (!res.success || !res.data) throw new Error(res.error || 'Upload failed');
      setFormData(prev => ({ ...prev, cover_image_id: res.data }));
    } catch (err: any) {
      setError(err.message || 'Image upload failed.');
    } finally {
      setUploadingImage(false);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const checked = (e.target as HTMLInputElement).checked;

    setFormData((prev) => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : type === 'number' ? Number(value) : value,
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    startTransition(async () => {
      try {
        const payload: CreateProgramDTO = {
          program_code: formData.program_code || '',
          slug: formData.slug || undefined, // undefined will auto-generate in service
          title: formData.title || '',
          subtitle: formData.subtitle || undefined,
          description: formData.description || undefined,
          status: formData.status as any,
          visibility: formData.visibility as any,
          is_featured: formData.is_featured || false,
          display_order: formData.display_order || 0,
          cover_image_id: formData.cover_image_id || undefined,
          metadata: initialData?.metadata || {},
        };

        if (initialData) {
          // Edit
          await updateProgram(initialData.id, payload);
        } else {
          // Create
          await createProgram(payload);
        }

        router.push('/admin/dashboard/programmes');
        router.refresh();
      } catch (err: any) {
        setError(err.message || 'An error occurred while saving the program.');
      }
    });
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6 max-w-3xl bg-white p-8 rounded-lg shadow-sm border border-gray-100">
      {error && (
        <div className="p-4 bg-red-50 text-red-700 text-sm rounded-md border border-red-100">
          {error}
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="space-y-2">
          <Label htmlFor="program_code">Program Code *</Label>
          <Input 
            id="program_code" 
            name="program_code" 
            value={formData.program_code} 
            onChange={handleChange} 
            placeholder="e.g. EDU-2026-01" 
            required 
            disabled={!!initialData} // Cannot edit code after creation based on typical constraints
          />
          <p className="text-xs text-gray-500">Unique alphanumeric code with hyphens.</p>
        </div>

        <div className="space-y-2">
          <Label htmlFor="slug">Slug (Optional)</Label>
          <Input 
            id="slug" 
            name="slug" 
            value={formData.slug} 
            onChange={handleChange} 
            placeholder="e.g. udbhav-siksha-samman" 
          />
          <p className="text-xs text-gray-500">Leave blank to auto-generate from title.</p>
        </div>
      </div>

      <div className="space-y-2">
        <Label htmlFor="title">Title *</Label>
        <Input 
          id="title" 
          name="title" 
          value={formData.title} 
          onChange={handleChange} 
          placeholder="Program Title" 
          required 
        />
      </div>

      <div className="space-y-2">
        <Label htmlFor="subtitle">Subtitle / Tagline</Label>
        <Input 
          id="subtitle" 
          name="subtitle" 
          value={formData.subtitle || ''} 
          onChange={handleChange} 
          placeholder="Short tagline for the program" 
        />
      </div>

      <div className="space-y-2">
        <Label htmlFor="description">Full Description</Label>
        <textarea 
          id="description" 
          name="description" 
          value={formData.description || ''} 
          onChange={handleChange} 
          rows={6}
          className="w-full flex min-h-[80px] rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
          placeholder="Detailed description of the program..." 
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="space-y-2">
          <Label htmlFor="status">Status</Label>
          <select 
            id="status" 
            name="status" 
            value={formData.status} 
            onChange={handleChange}
            className="w-full flex h-10 rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
          >
            <option value="draft">Draft</option>
            <option value="active">Published (Active)</option>
            <option value="archived">Archived</option>
          </select>
        </div>

        <div className="space-y-2">
          <Label htmlFor="visibility">Visibility</Label>
          <select 
            id="visibility" 
            name="visibility" 
            value={formData.visibility} 
            onChange={handleChange}
            className="w-full flex h-10 rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
          >
            <option value="public">Public</option>
            <option value="private">Private</option>
            <option value="internal">Internal</option>
          </select>
        </div>

        <div className="space-y-2">
          <Label htmlFor="display_order">Display Order</Label>
          <Input 
            id="display_order" 
            name="display_order" 
            type="number"
            min={0}
            value={formData.display_order} 
            onChange={handleChange} 
          />
        </div>
      </div>

      <div className="space-y-2 pt-4 border-t border-gray-100">
        <Label htmlFor="cover_image">Cover Image Upload</Label>
        <Input 
          id="cover_image" 
          type="file" 
          accept="image/*" 
          onChange={handleImageUpload} 
          disabled={uploadingImage || isPending}
        />
        {uploadingImage && <p className="text-sm text-blue-600">Uploading image...</p>}
        {formData.cover_image_id && <p className="text-sm text-green-600">Image attached successfully.</p>}
      </div>

      <div className="flex items-center gap-2 pt-4 border-t border-gray-100">
        <input 
          type="checkbox" 
          id="is_featured" 
          name="is_featured" 
          checked={formData.is_featured} 
          onChange={handleChange} 
          className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-600"
        />
        <Label htmlFor="is_featured" className="cursor-pointer">Feature on Homepage / Directory</Label>
      </div>

      <div className="pt-4 border-t border-gray-100 flex justify-end gap-4">
        <Button 
          type="button" 
          variant="outline" 
          onClick={() => router.push('/admin/dashboard/programmes')}
          disabled={isPending}
        >
          Cancel
        </Button>
        <Button type="submit" disabled={isPending}>
          {isPending ? 'Saving...' : initialData ? 'Update Program' : 'Create Program'}
        </Button>
      </div>
    </form>
  );
}

'use client';

import { Plus, Edit2, Trash2, ChevronRight, ChevronLeft, Upload, X, CheckCircle2 } from 'lucide-react';
import Image from 'next/image';
import React, { useState } from 'react';

import {
  createIndexInitiative,
  updateIndexInitiative,
  deleteIndexInitiative,
  manageIndexInitiativeGallery,
} from '@/features/index/actions';
import type { IndexInitiativeWithMedia } from '@/features/index/repository';
import { uploadMedia } from '@/features/media/actions';

interface AdminInitiativeManagerClientProps {
  initialInitiatives: IndexInitiativeWithMedia[];
}

export function AdminInitiativeManagerClient({ initialInitiatives }: AdminInitiativeManagerClientProps) {
  const [initiatives, setInitiatives] = useState<IndexInitiativeWithMedia[]>(initialInitiatives);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<IndexInitiativeWithMedia | null>(null);

  // Wizard state
  const [currentStep, setCurrentStep] = useState(1);
  const totalSteps = 6;

  // Form states
  const [title, setTitle] = useState('');
  const [slug, setSlug] = useState('');
  const [initiativeType, setInitiativeType] = useState('Education');
  const [year, setYear] = useState<number>(2026);
  const [location, setLocation] = useState('');

  const [coverMediaId, setCoverMediaId] = useState<string | null>(null);
  const [coverMediaUrl, setCoverMediaUrl] = useState<string | null>(null);

  const [shortSummary, setShortSummary] = useState('');
  const [description, setDescription] = useState('');

  const [beneficiaries, setBeneficiaries] = useState('');
  const [volunteers, setVolunteers] = useState('');
  const [chiefGuest, setChiefGuest] = useState('');
  const [outcome, setOutcome] = useState('');
  const [duration, setDuration] = useState('');
  const [partnerName, setPartnerName] = useState('');

  const [galleryIds, setGalleryIds] = useState<string[]>([]);
  const [galleryUrls, setGalleryUrls] = useState<{ id: string; public_url: string }[]>([]);

  const [status, setStatus] = useState<'Draft' | 'Published' | 'Archived'>('Published');

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [uploadingImage, setUploadingImage] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const resetForm = (item?: IndexInitiativeWithMedia) => {
    setCurrentStep(1);
    if (item) {
      setEditingItem(item);
      setTitle(item.title);
      setSlug(item.slug);
      setInitiativeType(item.initiative_type);
      setYear(item.year);
      setLocation(item.location || '');
      setCoverMediaId(item.cover_media_id || null);
      setCoverMediaUrl(item.cover_image_url || null);
      setShortSummary(item.short_summary);
      setDescription(item.description || '');
      setBeneficiaries(item.beneficiaries || '');
      setVolunteers(item.volunteers || '');
      setChiefGuest(item.chief_guest || '');
      setOutcome(item.outcome || '');
      setDuration(item.duration || '');
      setPartnerName(item.partner_name || '');
      setStatus(item.status);

      if (item.gallery) {
        setGalleryIds(item.gallery.map(g => g.media_id));
        setGalleryUrls(item.gallery.map(g => ({ id: g.media_id, public_url: g.public_url! })));
      } else {
        setGalleryIds([]);
        setGalleryUrls([]);
      }
    } else {
      setEditingItem(null);
      setTitle('');
      setSlug('');
      setInitiativeType('Education');
      setYear(2026);
      setLocation('');
      setCoverMediaId(null);
      setCoverMediaUrl(null);
      setShortSummary('');
      setDescription('');
      setBeneficiaries('');
      setVolunteers('');
      setChiefGuest('');
      setOutcome('');
      setDuration('');
      setPartnerName('');
      setStatus('Published');
      setGalleryIds([]);
      setGalleryUrls([]);
    }
    setErrorMessage(null);
  };

  const handleOpenModal = (item?: IndexInitiativeWithMedia) => {
    resetForm(item);
    setIsModalOpen(true);
  };

  const handleCoverUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      setUploadingImage(true);
      setErrorMessage(null);
      const formData = new FormData();
      formData.append('file', file);
      const res = await uploadMedia(formData);
      if (!res.success || !res.data) throw new Error(res.error || 'Upload failed');
      setCoverMediaId(res.data.id);
      setCoverMediaUrl(res.data.public_url);
    } catch (err: any) {
      setErrorMessage(err.message || 'Image upload failed');
    } finally {
      setUploadingImage(false);
    }
  };

  const handleGalleryUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;
    try {
      setUploadingImage(true);
      setErrorMessage(null);
      for (const file of files) {
        const formData = new FormData();
        formData.append('file', file);
        const res = await uploadMedia(formData);
        if (!res.success || !res.data) throw new Error(res.error || 'Upload failed for a file');
        setGalleryIds(prev => [...prev, res.data!.id]);
        setGalleryUrls(prev => [...prev, { id: res.data!.id, public_url: res.data!.public_url! }]);
      }
    } catch (err: any) {
      setErrorMessage(err.message || 'Gallery upload failed');
    } finally {
      setUploadingImage(false);
    }
  };

  const removeGalleryImage = (idToRemove: string) => {
    setGalleryIds(prev => prev.filter(id => id !== idToRemove));
    setGalleryUrls(prev => prev.filter(img => img.id !== idToRemove));
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (currentStep < totalSteps) {
      setCurrentStep(prev => prev + 1);
      return;
    }

    setIsSubmitting(true);
    setErrorMessage(null);

    try {
      const payload = {
        title,
        slug: slug || undefined,
        initiative_type: initiativeType,
        year,
        location: location || null,
        cover_media_id: coverMediaId,
        short_summary: shortSummary,
        description: description || null,
        beneficiaries: beneficiaries || null,
        volunteers: volunteers || null,
        chief_guest: chiefGuest || null,
        outcome: outcome || null,
        duration: duration || null,
        partner_name: partnerName || null,
        status,
      };

      let savedId = '';
      if (editingItem) {
        const res = await updateIndexInitiative(editingItem.id, payload);
        if (!res.success || !res.data) throw new Error(res.error || 'Failed to update initiative');
        savedId = res.data.id;

        // Sync gallery
        await manageIndexInitiativeGallery(savedId, { media_ids: galleryIds });

        setInitiatives((prev) =>
          prev.map((i) => (i.id === editingItem.id ? { ...i, ...res.data!, cover_image_url: coverMediaUrl, gallery: galleryUrls.map(g => ({ media_id: g.id, public_url: g.public_url, caption: null })) as any } : i))
        );
      } else {
        const res = await createIndexInitiative({ ...payload, featured: false, display_order: 0, seo_keywords: [] });
        if (!res.success || !res.data) throw new Error(res.error || 'Failed to create initiative');
        savedId = res.data.id;

        // Sync gallery
        if (galleryIds.length > 0) {
          await manageIndexInitiativeGallery(savedId, { media_ids: galleryIds });
        }

        const newItem = { ...res.data, cover_image_url: coverMediaUrl, gallery: galleryUrls.map(g => ({ media_id: g.id, public_url: g.public_url, caption: null })) };
        setInitiatives((prev) => [newItem as unknown as IndexInitiativeWithMedia, ...prev]);
      }
      setIsModalOpen(false);
    } catch (err) {
      setErrorMessage(err instanceof Error ? err.message : 'An error occurred');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm('Are you sure you want to delete this initiative?')) return;
    try {
      const res = await deleteIndexInitiative(id);
      if (res.success) {
        setInitiatives((prev) => prev.filter((i) => i.id !== id));
      }
    } catch {
      alert('Delete failed');
    }
  };

  const statusColors = {
    Published: 'bg-green-100 text-green-800',
    Draft: 'bg-yellow-100 text-yellow-800',
    Archived: 'bg-gray-100 text-gray-800',
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Programs &amp; Initiatives Archive</h1>
