/**
 * Service layer for user notification operations.
 */
export class NotificationsService {
  /**
   * Lists notifications for a given user ordered by latest created_at.
   *
   * @param userId - Target user ID.
   * @param pagination - Pagination options.
   * @returns ServiceResult wrapping PaginatedResult of NotificationRow items.
   */
  async list(
    userId: ID,
    pagination: Pagination
  ): Promise<ServiceResult<PaginatedResult<NotificationRow>>> {
    try {
      const supabase = await createServerSupabaseClient();
      const from = (pagination.page - 1) * pagination.limit;
      const { data, count, error } = await supabase
        .from('notifications')
        .select('*', { count: 'exact' })
        .eq('user_id', userId)
        .order('created_at', { ascending: false })
        .range(from, from + pagination.limit - 1);
      if (error) return fail(error.message);
      return ok({
        data: data ?? [],
        total: count ?? 0,
        page: pagination.page,
        limit: pagination.limit,
      });
    } catch (error) {
      serverLogger.error('NotificationsService.list failed', error as Error);
      return fail('Failed to fetch notifications.');
    }
  }

  /**
   * Marks a single notification as read by setting read_at timestamp.
   *
   * @param id - Notification ID.
   * @returns ServiceResult wrapping updated NotificationRow.
   */
  async markRead(id: ID): Promise<ServiceResult<NotificationRow>> {
    try {
      const supabase = await createServerSupabaseClient();
      const { data, error } = await (supabase.from('notifications') as any)
        .update({ read_at: new Date().toISOString() })
        .eq('id', id)
        .select()
        .single();
      if (error) return fail(error.message);
      return ok(data);
    } catch (error) {
      serverLogger.error('NotificationsService.markRead failed', error as Error);
      return fail('Failed to mark notification.');
    }
  }

  /**
   * Marks all unread notifications as read for a given user.
   *
   * @param userId - Target user ID.
   * @returns ServiceResult wrapping count of marked notifications.
   */
  async markAllRead(userId: ID): Promise<ServiceResult<number>> {
    try {
      const supabase = await createServerSupabaseClient();
      const { count, error } = await (supabase.from('notifications') as any)
        .update({ read_at: new Date().toISOString() })
        .eq('user_id', userId)
        .is('read_at', null)
        .select('id');
      if (error) return fail(error.message);
      return ok(count ?? 0);
    } catch (error) {
      serverLogger.error('NotificationsService.markAllRead failed', error as Error);
      return fail('Failed to mark all.');
    }
  }
}

